<?= $this->extend('layouts/store') ?><?= $this->section('content') ?><section class="narrow"><p class="eyebrow">Account</p><h1>Your orders.</h1><?php foreach($orders as $o): ?><a class="cart-row" href="<?= base_url('orders/'.$o['id']) ?>"><strong><?= esc(order_number($o)) ?></strong><span><?= date('d M Y',strtotime($o['created_at'])) ?></span><span><?= ucfirst($o['status']) ?></span><strong>₹<?= number_format($o['total_amount'],2) ?></strong></a><?php endforeach ?><?php if(!$orders): ?><p>No orders yet.</p><?php endif ?></section><?= $this->endSection() ?>
